name: PR Title Check

on:
  pull_request:
    types: [opened, edited, synchronize]

concurrency:
  group: ${{ github.workflow }}-${{ github.event.pull_request.number || github.ref }}
  cancel-in-progress: true

# Add permissions for the GITHUB_TOKEN
permissions:
  pull-requests: read
  contents: read

jobs:
  check-pr-title:
    runs-on: ubuntu-latest
    steps:
      - name: Check PR Title Convention
        uses: actions/github-script@v7
        with:
          script: |
            const title = context.payload.pull_request.title;

            // Define allowed prefixes (conventional commit types)
            const allowedPrefixes = [
              'feat', 'fix', 'docs', 'style', 'refactor',
              'test', 'chore', 'perf', 'ci', 'build',
              'revert', 'hotfix'
            ];

            // Define the regex pattern for PR title validation
            // Format: type(scope): description
            // Examples:
            // - feat: add user authentication
            // - fix(api): resolve timeout issue
            // - docs(readme): update installation guide
            const titleRegex = /^(feat|fix|docs|style|refactor|test|chore|perf|ci|build|revert|hotfix)(\(.+\))?: .+/;

            console.log(`Checking PR title: "${title}"`);

            if (!titleRegex.test(title)) {
              // Fail the check with detailed message
              core.setFailed(`PR title "${title}" doesn't follow the required convention. Required format: type(scope): description. Valid types: ${allowedPrefixes.join(', ')}`);
            } else {
              console.log('✅ PR title follows the required convention!');
            }

apiVersion: v1
data:
  LOCKER__DATABASE__PASSWORD: {{ include "locker-psql.password" . | b64enc }}
  LOCKER__SECRETS__LOCKER_PRIVATE_KEY: {{ .Values.secrets.locker_private_key | b64enc }}
  LOCKER__TENANT_SECRETS__PUBLIC__MASTER_KEY: {{ .Values.tenant_secrets.public.master_key | b64enc }}
  LOCKER__TENANT_SECRETS__PUBLIC__PUBLIC_KEY: {{ .Values.tenant_secrets.public.public_key | b64enc }}
  {{- if .Values.vaultKeysJob.enabled }}
  CUSTODIAN__KEY1: {{ .Values.vaultKeysJob.keys.key1 | b64enc }}
  CUSTODIAN__KEY2: {{ .Values.vaultKeysJob.keys.key2 | b64enc }}
  {{- end }}

  {{- if eq .Values.backend "aws_kms" }}
  LOCKER__SECRETS_MANAGEMENT__AWS_KMS__KEY_ID: {{ .Values.secrets.aws.key_id | b64enc }}
  LOCKER__SECRETS_MANAGEMENT__AWS_KMS__REGION: {{ .Values.secrets.aws.region | b64enc }}
  {{- else if eq .Values.backend "hashi_corp_vault" }}
  LOCKER__SECRETS_MANAGEMENT__HASHI_CORP_VAULT__TOKEN: {{ .Values.secrets.vault.token | b64enc }}
  {{- end }}

  {{- if .Values.secrets.tls.certificate }}
  LOCKER__TLS__CERTIFICATE: {{ .Values.secrets.tls.certificate | b64enc }}
  {{- end }}
  {{- if .Values.secrets.tls.private_key }}
  LOCKER__TLS__PRIVATE_KEY: {{ .Values.secrets.tls.private_key | b64enc }}
  {{- end }}

  {{- if eq .Values.server.external_key_manager.mode "enabled_with_mtls" }}
  {{- if .Values.secrets.external_key_manager.caCert }}
  LOCKER__EXTERNAL_KEY_MANAGER__CA_CERT: {{ .Values.secrets.external_key_manager.caCert | b64enc }}
  {{- end }}
  {{- if .Values.secrets.api_client.identity }}
  LOCKER__API_CLIENT__IDENTITY: {{ .Values.secrets.api_client.identity | b64enc }}
  {{- end }}
  {{- end }}
kind: Secret
metadata:
  name: locker-secrets-{{ .Release.Name }}
  namespace: {{ .Release.Namespace }}
type: Opaque

{{- if not .Values.disableInternalSecrets }}
{{- /*
Chart-managed Secret holding every `_secret` value under `config`, as CS__* keys.
Always rendered (possibly empty) so the deployment's envFrom.secretRef resolves;
set disableInternalSecrets: true when every secret is delivered by a `_secretRef`
or the External Secrets Operator instead.
*/}}
apiVersion: v1
kind: Secret
metadata:
  name: {{ .Release.Name }}-hyperswitch-ucs-secrets
  namespace: {{ .Release.Namespace }}
  labels:
    {{- include "hyperswitch-ucs.labels" . | nindent 4 }}
    app.kubernetes.io/component: secret
type: Opaque
{{- with include "hyperswitch-ucs.configToSecrets" (dict "config" .Values.config "prefix" "CS") | trim }}
data:
  {{- . | nindent 2 }}
{{- end }}
{{- end }}

